import{_ as B,C as s,o as e,c as n,a2 as d,b as l,w as a,a as r,E as A,a3 as i,j as t}from"./chunks/framework.CAKCj7G0.js";const m=JSON.parse('{"title":"Elasticsearch 倒排索引详解","description":"","frontmatter":{},"headers":[],"relativePath":"数据库/ES/特性/倒排索引.md","filePath":"数据库/ES/特性/倒排索引.md","lastUpdated":1767010008000}'),h={name:"数据库/ES/特性/倒排索引.md"};function c(D,E,F,u,p,C){const o=s("Mermaid");return e(),n("div",null,[E[2]||(E[2]=d('<h1 id="elasticsearch-倒排索引详解" tabindex="-1">Elasticsearch 倒排索引详解 <a class="header-anchor" href="#elasticsearch-倒排索引详解" aria-label="Permalink to &quot;Elasticsearch 倒排索引详解&quot;">​</a></h1><p>Elasticsearch 的核心检索能力完全依赖倒排索引，它是一种专为全文搜索设计的数据结构，与传统数据库的正排索引（行→列值）逻辑相反，能实现快速的关键词匹配。</p><h2 id="核心概念-正排-vs-倒排" tabindex="-1">核心概念：正排 vs 倒排 <a class="header-anchor" href="#核心概念-正排-vs-倒排" aria-label="Permalink to &quot;核心概念：正排 vs 倒排&quot;">​</a></h2><h3 id="正排索引" tabindex="-1">正排索引 <a class="header-anchor" href="#正排索引" aria-label="Permalink to &quot;正排索引&quot;">​</a></h3><p>传统数据库的存储逻辑，以文档（行）为中心，记录每个文档包含的内容：</p><table tabindex="0"><thead><tr><th>文档ID</th><th>内容（字段值）</th></tr></thead><tbody><tr><td>1</td><td>I love Elasticsearch</td></tr><tr><td>2</td><td>Elasticsearch is powerful</td></tr></tbody></table><p>查询时需要遍历所有文档，逐个判断是否包含目标关键词，效率极低（时间复杂度 O(n)）。</p><h3 id="倒排索引" tabindex="-1">倒排索引 <a class="header-anchor" href="#倒排索引" aria-label="Permalink to &quot;倒排索引&quot;">​</a></h3><p>以关键词（词条）为中心，记录每个关键词出现在哪些文档中，结构分为两部分：</p><ul><li><strong>词典（Term Dictionary）</strong>：去重后的所有关键词列表，通常用跳表/前缀树优化查询</li><li><strong>倒排列表（Posting List）</strong>：每个关键词对应的文档ID集合，还可附带词频、位置等信息</li></ul><p>以上面的文档为例，分词后的倒排索引结构如下：</p><table tabindex="0"><thead><tr><th>关键词（Term）</th><th>倒排列表（文档ID + 附加信息）</th></tr></thead><tbody><tr><td>love</td><td>[1, 词频=1, 位置=2]</td></tr><tr><td>elasticsearch</td><td>[1, 词频=1, 位置=3], [2, 词频=1, 位置=1]</td></tr><tr><td>powerful</td><td>[2, 词频=1, 位置=3]</td></tr></tbody></table><p>查询 <code>Elasticsearch</code> 时，直接通过词典找到该关键词，再读取对应的文档ID列表，无需遍历所有文档，效率极高（时间复杂度 O(1)）。</p><hr><h2 id="es-倒排索引的构建流程" tabindex="-1">ES 倒排索引的构建流程 <a class="header-anchor" href="#es-倒排索引的构建流程" aria-label="Permalink to &quot;ES 倒排索引的构建流程&quot;">​</a></h2><p>ES 构建倒排索引的过程发生在文档写入阶段，与分词器、映射配置强相关。</p><h3 id="构建流程图" tabindex="-1">构建流程图 <a class="header-anchor" href="#构建流程图" aria-label="Permalink to &quot;构建流程图&quot;">​</a></h3>',17)),(e(),l(i,null,{default:a(()=>[A(o,{id:"mermaid-120",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5B%E5%86%99%E5%85%A5%E6%96%87%E6%A1%A3%EF%BC%9AJSON%E6%A0%BC%E5%BC%8F%5D%20--%3E%20B%5B%E8%A7%A3%E6%9E%90%E6%96%87%E6%A1%A3%EF%BC%8C%E6%8F%90%E5%8F%96%E5%AD%97%E6%AE%B5%E5%80%BC%5D%0A%20%20%20%20B%20--%3E%20C%5B%E5%AD%97%E6%AE%B5%E9%A2%84%E5%A4%84%E7%90%86%EF%BC%9A%E8%BF%87%E6%BB%A4HTML%2F%E7%89%B9%E6%AE%8A%E5%AD%97%E7%AC%A6%5D%0A%20%20%20%20C%20--%3E%20D%7B%E5%AD%97%E6%AE%B5%E7%B1%BB%E5%9E%8B%E5%88%A4%E6%96%AD%7D%0A%20%20%20%20D%20--%3E%7Ctext%E7%B1%BB%E5%9E%8B%7C%20E%5B%E5%88%86%E8%AF%8D%E5%99%A8%E5%A4%84%E7%90%86%EF%BC%9A%E6%8B%86%E5%88%86%E4%B8%BA%E8%AF%8D%E6%9D%A1%5D%0A%20%20%20%20D%20--%3E%7Ckeyword%2F%E6%95%B0%E5%80%BC%E7%B1%BB%E5%9E%8B%7C%20F%5B%E4%B8%8D%E5%88%86%E8%AF%8D%EF%BC%8C%E7%9B%B4%E6%8E%A5%E4%BD%9C%E4%B8%BA%E5%8D%95%E4%B8%AA%E8%AF%8D%E6%9D%A1%5D%0A%20%20%20%20E%20--%3E%20G%5B%E8%AF%8D%E6%9D%A1%E6%A0%87%E5%87%86%E5%8C%96%EF%BC%9A%E5%B0%8F%E5%86%99%E8%BD%AC%E6%8D%A2%2F%E8%AF%8D%E5%B9%B2%E6%8F%90%E5%8F%96%5D%0A%20%20%20%20F%20--%3E%20G%0A%20%20%20%20G%20--%3E%20H%5B%E6%9E%84%E5%BB%BA%E8%AF%8D%E5%85%B8%EF%BC%9A%E5%8E%BB%E9%87%8D%2B%E6%8E%92%E5%BA%8F%E6%89%80%E6%9C%89%E8%AF%8D%E6%9D%A1%5D%0A%20%20%20%20G%20--%3E%20I%5B%E6%9E%84%E5%BB%BA%E5%80%92%E6%8E%92%E5%88%97%E8%A1%A8%EF%BC%9A%E8%AF%8D%E6%9D%A1%E2%86%92%E6%96%87%E6%A1%A3ID%2F%E8%AF%8D%E9%A2%91%2F%E4%BD%8D%E7%BD%AE%5D%0A%20%20%20%20H%20%26%20I%20--%3E%20J%5B%E5%86%99%E5%85%A5%E7%A3%81%E7%9B%98%EF%BC%8C%E7%94%9F%E6%88%90%E5%88%86%E6%AE%B5%EF%BC%88Segment%EF%BC%89%5D%0A%20%20%20%20J%20--%3E%20K%5B%E5%AE%9A%E6%9C%9F%E5%90%88%E5%B9%B6%E5%88%86%E6%AE%B5%EF%BC%8C%E4%BC%98%E5%8C%96%E6%9F%A5%E8%AF%A2%E6%80%A7%E8%83%BD%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[r(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=d('<h3 id="文档解析与预处理" tabindex="-1">文档解析与预处理 <a class="header-anchor" href="#文档解析与预处理" aria-label="Permalink to &quot;文档解析与预处理&quot;">​</a></h3><p>ES 先将 JSON 文档解析为字段-值对，过滤掉无效字符（如 HTML 标签、转义符）。</p><p>示例：字段 <code>content: &quot;I Love ES!&quot;</code> 预处理后变为 <code>I Love ES</code>。</p><h3 id="分词处理-text-字段核心步骤" tabindex="-1">分词处理（text 字段核心步骤） <a class="header-anchor" href="#分词处理-text-字段核心步骤" aria-label="Permalink to &quot;分词处理（text 字段核心步骤）&quot;">​</a></h3><p>分词器（如 <code>standard</code>/<code>ik_max_word</code>）将文本拆分为独立词条，并做标准化处理：</p><ul><li>小写转换：<code>Love</code> → <code>love</code></li><li>词干提取（英文）：<code>running</code> → <code>run</code></li><li>停用词过滤：去掉 <code>the</code>/<code>a</code> 等无意义词汇</li></ul><p>示例：<code>I Love ES</code> → 分词后为 <code>[i, love, es]</code></p><h3 id="词典与倒排列表构建" tabindex="-1">词典与倒排列表构建 <a class="header-anchor" href="#词典与倒排列表构建" aria-label="Permalink to &quot;词典与倒排列表构建&quot;">​</a></h3><ul><li><strong>词典</strong>：收集所有字段的标准化词条，去重并排序，方便快速查找</li><li><strong>倒排列表</strong>：为每个词条记录对应的文档ID、词频（TF，词条在文档中出现次数）、位置（词条在文本中的偏移量），这些信息用于计算相关性评分（BM25）</li></ul><h3 id="分段存储与合并" tabindex="-1">分段存储与合并 <a class="header-anchor" href="#分段存储与合并" aria-label="Permalink to &quot;分段存储与合并&quot;">​</a></h3><p>ES 不会一次性将所有文档写入一个大索引，而是拆分为多个分段（Segment）存储在磁盘。后台会定期合并小分段为大分段，减少查询时的 IO 开销，同时清理已删除的文档。</p><hr><h2 id="倒排索引的核心特性" tabindex="-1">倒排索引的核心特性 <a class="header-anchor" href="#倒排索引的核心特性" aria-label="Permalink to &quot;倒排索引的核心特性&quot;">​</a></h2><h3 id="只读不可变" tabindex="-1">只读不可变 <a class="header-anchor" href="#只读不可变" aria-label="Permalink to &quot;只读不可变&quot;">​</a></h3><p>一旦分段写入磁盘，就会变成只读状态，无法修改。</p><ul><li><strong>优点</strong>：避免并发写入冲突，查询时无需加锁，提升性能</li><li><strong>缺点</strong>：更新/删除文档时，不会直接修改旧分段，而是标记文档为已删除，并在新分段中写入更新后的内容，合并分段时才会清理无效数据</li></ul><h3 id="支持多维度附加信息" tabindex="-1">支持多维度附加信息 <a class="header-anchor" href="#支持多维度附加信息" aria-label="Permalink to &quot;支持多维度附加信息&quot;">​</a></h3><p>倒排列表除了文档ID，还会存储：</p><ul><li><strong>词频（TF）</strong>：词条在文档中出现的次数，次数越多，相关性评分越高</li><li><strong>位置（Position）</strong>：用于实现短语查询（如 <code>match_phrase: &quot;Elasticsearch tutorial&quot;</code>），要求词条按顺序出现</li><li><strong>偏移量（Offset）</strong>：用于高亮显示搜索结果中的匹配关键词</li></ul><h3 id="与映射-mapping-强绑定" tabindex="-1">与映射（Mapping）强绑定 <a class="header-anchor" href="#与映射-mapping-强绑定" aria-label="Permalink to &quot;与映射（Mapping）强绑定&quot;">​</a></h3><ul><li><code>text</code> 类型字段会分词，生成多词条的倒排索引，适合全文搜索</li><li><code>keyword</code> 类型字段不分词，直接以整个字符串作为词条，适合精确匹配、聚合</li><li>数值类型（<code>integer</code>/<code>date</code>）会被编码为词条，支持范围查询</li></ul><hr><h2 id="倒排索引与-es-核心功能的关系" tabindex="-1">倒排索引与 ES 核心功能的关系 <a class="header-anchor" href="#倒排索引与-es-核心功能的关系" aria-label="Permalink to &quot;倒排索引与 ES 核心功能的关系&quot;">​</a></h2><table tabindex="0"><thead><tr><th>功能</th><th>实现原理</th></tr></thead><tbody><tr><td><strong>全文搜索</strong></td><td>直接通过词典匹配关键词，快速获取文档列表</td></tr><tr><td><strong>相关性评分（BM25）</strong></td><td>基于倒排列表中的词频（TF）、文档频率（DF，词条在所有文档中出现的次数）计算评分，决定搜索结果的排序</td></tr><tr><td><strong>聚合分析</strong></td><td>对 <code>keyword</code>/数值字段的倒排索引进行分组统计，实现 <code>terms</code>/<code>range</code> 等聚合</td></tr><tr><td><strong>过滤查询</strong></td><td>通过倒排索引快速筛选符合条件的文档，过滤后的结果会缓存，提升重复查询性能</td></tr></tbody></table><hr><h2 id="查询流程可视化" tabindex="-1">查询流程可视化 <a class="header-anchor" href="#查询流程可视化" aria-label="Permalink to &quot;查询流程可视化&quot;">​</a></h2>',26)),(e(),l(i,null,{default:a(()=>[A(o,{id:"mermaid-296",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20subgraph%20%E7%B4%A2%E5%BC%95%E6%9E%84%E5%BB%BA%E9%98%B6%E6%AE%B5%0A%20%20%20%20%20%20%20%20A%5B%E6%96%87%E6%A1%A3%E5%86%99%E5%85%A5%5D%20--%3E%20B%5B%E5%88%86%E8%AF%8D%2B%E6%A0%87%E5%87%86%E5%8C%96%5D%0A%20%20%20%20%20%20%20%20B%20--%3E%20C%5B%E7%94%9F%E6%88%90%E8%AF%8D%E5%85%B8%2B%E5%80%92%E6%8E%92%E5%88%97%E8%A1%A8%5D%0A%20%20%20%20%20%20%20%20C%20--%3E%20D%5B%E5%AD%98%E5%82%A8%E4%B8%BA%E5%8F%AA%E8%AF%BB%E5%88%86%E6%AE%B5%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20%E6%9F%A5%E8%AF%A2%E9%98%B6%E6%AE%B5%0A%20%20%20%20%20%20%20%20E%5B%E7%94%A8%E6%88%B7%E8%BE%93%E5%85%A5%E6%9F%A5%E8%AF%A2%E8%AF%8D%EF%BC%9AElasticsearch%5D%20--%3E%20F%5B%E5%88%86%E8%AF%8D%2B%E6%A0%87%E5%87%86%E5%8C%96%EF%BC%9Aelasticsearch%5D%0A%20%20%20%20%20%20%20%20F%20--%3E%20G%5B%E6%9F%A5%E8%AF%A2%E8%AF%8D%E5%85%B8%EF%BC%8C%E6%89%BE%E5%88%B0%E8%AF%8D%E6%9D%A1%5D%0A%20%20%20%20%20%20%20%20G%20--%3E%20H%5B%E8%AF%BB%E5%8F%96%E5%80%92%E6%8E%92%E5%88%97%E8%A1%A8%EF%BC%8C%E8%8E%B7%E5%8F%96%E6%96%87%E6%A1%A3ID%E5%88%97%E8%A1%A8%5D%0A%20%20%20%20%20%20%20%20H%20--%3E%20I%5B%E8%AE%A1%E7%AE%97%E7%9B%B8%E5%85%B3%E6%80%A7%E8%AF%84%E5%88%86%EF%BC%8C%E6%8E%92%E5%BA%8F%E7%BB%93%E6%9E%9C%5D%0A%20%20%20%20%20%20%20%20I%20--%3E%20J%5B%E8%BF%94%E5%9B%9E%E9%AB%98%E4%BA%AE%E5%90%8E%E7%9A%84%E6%96%87%E6%A1%A3%5D%0A%20%20%20%20end%0A%0A%20%20%20%20D%20--%3E%7C%E6%8F%90%E4%BE%9B%E6%95%B0%E6%8D%AE%7C%20G%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[r(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=t("hr",null,null,-1)),E[5]||(E[5]=t("h2",{id:"总结",tabindex:"-1"},[r("总结 "),t("a",{class:"header-anchor",href:"#总结","aria-label":'Permalink to "总结"'},"​")],-1)),E[6]||(E[6]=t("ol",null,[t("li",null,"倒排索引是 ES 实现高效全文搜索的核心，核心结构是词典 + 倒排列表，以词条为中心反向映射文档"),t("li",null,"构建过程依赖分词器和映射配置，生成的分段只读不可变，通过后台合并优化性能"),t("li",null,"倒排列表中的词频、位置等信息，支撑了 ES 的相关性评分、短语查询、高亮等核心功能")],-1))])}const g=B(h,[["render",c]]);export{m as __pageData,g as default};
